import { useCallback, useEffect, useRef, useState } from 'react';
import { ArrowDownToLine, ArrowLeft, ArrowRight, Archive, BriefcaseBusiness, Building2, CheckCircle2, ChevronRight, CircleAlert, Clock3, Database, FileSpreadsheet, Globe2, LayoutDashboard, Mail, MapPin, Plus, Search, Settings2, ShieldCheck, SlidersHorizontal, Trash2, Upload, Wrench, Pencil, RotateCcw, Phone, CalendarDays, GitBranch, List } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import type { CRMData, Customer, Project, AfterSalesCase, Followup, Relationship } from './types';
import { CUSTOMER_STATUSES, CUSTOMER_TYPES, PROJECT_STATUSES, CASE_STATUSES, today } from './types';
import { loadData, saveData, validateBackup, getStorageInfo, switchWorkspace, refreshStorageInfo } from './data/store';
import { exportExcel, exportBackup, buildBackup } from './data/export';
import { CustomerForm, ProjectForm, CaseForm, FollowupForm } from './components/Forms';
import { StageBoard, FollowupTimeline } from './components/Workflow';
import { CustomerJourneyMap } from './components/CustomerJourneyMap';
import { CustomerTopology } from './components/CustomerTopology';
import { RelationshipForm } from './components/RelationshipForm';
import { WorkspacePanel } from './components/WorkspacePanel';
import { Badge, Button, Empty, Modal } from './components/UI';
import { amountText, customerName, dateText, daysSince, isDue, stageName, tone, withinWeek } from './utils';

type Form = { kind: 'customer'; initial?: Customer } | { kind: 'project'; initial?: Project; customerId?: string } | { kind: 'case'; initial?: AfterSalesCase; customerId?: string } | { kind: 'log'; entity: 'customer' | 'project' | 'case'; id: string; initial?: Followup } | { kind: 'relationship'; initial?: Relationship };
type Confirmation = { title: string; description: string; action: () => Promise<void>; danger?: boolean };
const flags: Record<string,string> = { 德国: '🇩🇪', 荷兰: '🇳🇱', 捷克: '🇨🇿', 匈牙利: '🇭🇺', 克罗地亚: '🇭🇷', 黑山: '🇲🇪' };
const goto = (path: string) => { window.location.hash = `/${path}`; };
const pathNow = () => window.location.hash.replace(/^#\/?/, '').split('/');
const errorText = (e: unknown) => e instanceof Error ? e.message : '操作失败，请重试';
const updated = <T extends { updatedAt: string }>(record: T): T => ({ ...record, updatedAt: new Date().toISOString() });
const latestDate = (logs: Followup[], fallback = '') => [...logs.map(l=>l.date).filter(Boolean), fallback].sort().at(-1) ?? '';

export default function App() {
  const [data, setData] = useState<CRMData | null>(null);
  const dataRef = useRef<CRMData | null>(null);
  const displayedScope = useRef<{ userId: string; workspaceId: string } | null>(null);
  const [loadError, setLoadError] = useState('');
  const [path, setPath] = useState(pathNow);
  const [form, updateForm] = useState<Form | null>(null);
  const [storage, setStorage] = useState<ReturnType<typeof getStorageInfo> | null>(null);
  const [syncError, setSyncError] = useState('');
  const [inviteToken, setInviteToken] = useState(() => new URLSearchParams(window.location.search).get('invite') ?? '');
  const [inviteBusy, setInviteBusy] = useState(false);
  const [inviteError, setInviteError] = useState('');
  const pendingWrites = useRef(0);
  const [confirmation, setConfirmation] = useState<Confirmation | null>(null);
  const [confirmBusy, setConfirmBusy] = useState(false);
  const [confirmError, setConfirmError] = useState('');
  const [notice, setNotice] = useState<{ message: string; error?: boolean } | null>(null);
  const [exportBusy, setExportBusy] = useState(false);
  const [restore, setRestore] = useState<CRMData | null>(null);
  const [restoreWord, setRestoreWord] = useState('');
  const [restoreBusy, setRestoreBusy] = useState(false);
  const [restoreError, setRestoreError] = useState('');
  const [pasteBackup, setPasteBackup] = useState(false);
  const [backupText, setBackupText] = useState('');
  const [backupTextError, setBackupTextError] = useState('');
  const [viewBackup, setViewBackup] = useState(false);
  const [tab, setTab] = useState<'projects'|'cases'|'logs'>('projects');
  const [customerView, setCustomerView] = useState<'map'|'table'>('map');
  const [query, setQuery] = useState('');
  const [country, setCountry] = useState('');
  const [kind, setKind] = useState('');
  const [status, setStatus] = useState('');
  const [showArchived, setShowArchived] = useState(false);
  const [sort, setSort] = useState('updated');
  const [followupFilter, setFollowupFilter] = useState('');
  const importRef = useRef<HTMLInputElement>(null);
  const queue = useRef<Promise<unknown>>(Promise.resolve());
  const notify = useCallback((message: string, error = false) => setNotice({ message, error }), []);
  const applyLoaded = useCallback((value: CRMData) => { const scope=getStorageInfo(); displayedScope.current={userId:scope.user?.id??'',workspaceId:scope.currentWorkspaceId}; dataRef.current = value; setData(value); }, []);
  const boot = useCallback(async () => { setLoadError(''); try { applyLoaded(await loadData()); setStorage(getStorageInfo()); setSyncError(''); } catch(e) { setLoadError(errorText(e)); } }, [applyLoaded]);
  useEffect(() => { void boot(); }, [boot]);
  useEffect(() => { const handler = () => { setPath(pathNow()); setQuery(''); setCountry(''); setStatus(''); setKind(''); setTab('projects'); setCustomerView('map'); setFollowupFilter(''); }; window.addEventListener('hashchange', handler); return () => window.removeEventListener('hashchange', handler); }, []);
  useEffect(() => { window.scrollTo({ top: 0, behavior: 'auto' }); }, [path]);
  useEffect(() => { if (!notice) return; const timer = window.setTimeout(()=>setNotice(null), notice.error ? 9000 : 4500); return ()=>clearTimeout(timer); }, [notice]);
  useEffect(() => {
    if (storage?.mode !== 'cloud') return;
    const refresh = async () => {
      if (pendingWrites.current || document.querySelector('[role="dialog"]') || document.visibilityState === 'hidden') return;
      const workspaceId = getStorageInfo()?.currentWorkspaceId;
      try { const value = await loadData(); const loadedScope=getStorageInfo();if(displayedScope.current?.userId!==(loadedScope.user?.id??'')||displayedScope.current?.workspaceId!==loadedScope.currentWorkspaceId){dataRef.current=null;setData(null);setLoadError('账户或工作空间已变更，请重新加载。');return;} if (pendingWrites.current || document.querySelector('[role="dialog"]') || getStorageInfo()?.currentWorkspaceId !== workspaceId || (dataRef.current && value.revision < dataRef.current.revision)) return; applyLoaded(value); setStorage(getStorageInfo()); setSyncError(''); }
      catch (e) { setSyncError(errorText(e)); }
    };
    const timer = window.setInterval(() => { void refresh(); }, 15000);
    return () => clearInterval(timer);
  }, [storage?.mode, storage?.currentWorkspaceId, applyLoaded]);
  const setForm = (value: Form | null) => { if (value && storage?.role === 'viewer') { notify('当前工作空间为只读权限', true); return; } updateForm(value); };
  const commit = useCallback((mutate: (draft: CRMData) => void, message?: string) => {
    pendingWrites.current++;
    const run = async () => {
      if (getStorageInfo()?.role === 'viewer') throw new Error('当前工作空间为只读权限');
      const scope=getStorageInfo();
      if (scope.mode==='cloud' && (displayedScope.current?.userId!==scope.user?.id || displayedScope.current?.workspaceId!==scope.currentWorkspaceId)) { dataRef.current=null;setData(null);setLoadError('账户或工作空间已变更，请重新加载后编辑。');throw new Error('当前草稿属于之前的工作空间，没有保存到新账户。'); }
      if (!dataRef.current) throw new Error('数据尚未加载');
      const current = dataRef.current;
      const next = structuredClone(current);
      mutate(next);
      try { applyLoaded(await saveData(next, current.revision)); setStorage(getStorageInfo()); setSyncError(''); notify(message ?? (getStorageInfo()?.mode === 'cloud' ? '保存成功，已同步到云端' : '保存成功，数据已写入本地')); }
      catch(e) { notify(errorText(e), true); throw e; }
    };
    const task = queue.current.then(run, run).finally(() => { pendingWrites.current--; }); queue.current = task.catch(()=>{}); return task;
  }, [applyLoaded,notify]);
  const runSafely = (operation: () => Promise<void>) => { void operation().catch(e=>notify(errorText(e),true)); };
  const ask = (item: Confirmation) => { setConfirmError(''); setConfirmation(item); };
  const downloadExcel = async () => { if (!dataRef.current) return; setExportBusy(true); try { await exportExcel(dataRef.current); notify('Excel 报表已生成，请查看浏览器下载'); } catch(e) { notify(errorText(e),true); } finally { setExportBusy(false); } };
  const downloadBackup = () => { if(dataRef.current) { try { exportBackup(dataRef.current); notify('全部数据备份已生成，请查看浏览器下载'); } catch(e) { notify(errorText(e),true); } } };
  const selectBackup = async (file?: File) => { if(!file) return; try { if (file.size > 30 * 1024 * 1024) throw new Error('备份文件超过 30 MB，请检查文件'); const parsed = validateBackup(JSON.parse(await file.text())); setRestore(parsed); setRestoreWord(''); setRestoreError(''); } catch(e) { notify(`无法导入：${errorText(e)}`,true); } finally { if(importRef.current) importRef.current.value=''; } };
  const previewBackupText = () => { try { if(new Blob([backupText]).size>30*1024*1024) throw new Error('备份超过 30 MB，请检查内容'); const parsed=validateBackup(JSON.parse(backupText)); setRestore(parsed);setRestoreWord('');setRestoreError('');setPasteBackup(false);setBackupText(''); } catch(e) { setBackupTextError(errorText(e)); } };
  const restoreBackup = async () => { if(!restore || restoreWord !== '恢复') return; setRestoreBusy(true); setRestoreError(''); try { if(dataRef.current) exportBackup(dataRef.current); await commit(draft=> { draft.customers=restore.customers; draft.projects=restore.projects; draft.cases=restore.cases; draft.relationships=restore.relationships; },'恢复成功，全部记录已保存'); setRestore(null); goto('customers'); } catch(e) { setRestoreError(errorText(e)); } finally { setRestoreBusy(false); } };
  const saveCustomer = async (value: Customer) => { await commit(d=> { const i=d.customers.findIndex(c=>c.id===value.id); i<0 ? d.customers.push(updated(value)) : d.customers.splice(i,1,updated(value)); }); setForm(null); goto(`customers/${value.id}`); };
  const saveRelationship = async (value: Relationship) => { await commit(d => { if(d.relationships.some(r => r.id !== value.id && r.fromCustomerId === value.fromCustomerId && r.toCustomerId === value.toCustomerId && r.type === value.type)) throw new Error('这条关系已存在'); const i=d.relationships.findIndex(r=>r.id===value.id); i<0 ? d.relationships.push(value) : d.relationships.splice(i,1,value); }); setForm(null); };
  const changeWorkspace = async (id: string) => { if (pendingWrites.current || document.querySelector('[role="dialog"]')) throw new Error('请先完成当前编辑'); await switchWorkspace(id); dataRef.current=null; setData(null); goto('dashboard'); await boot(); };
  const saveProject = async (value: Project) => { await commit(d=> { if(d.cases.some(c=>c.projectId===value.id && c.customerId!==value.customerId)) throw new Error('该项目有关联售后案例，请先解除案例关联后再更换客户'); const i=d.projects.findIndex(p=>p.id===value.id); i<0 ? d.projects.push(updated(value)) : d.projects.splice(i,1,updated(value)); }); setForm(null); goto(`projects/${value.id}`); };
  const saveCase = async (value: AfterSalesCase) => { await commit(d=> { if(d.cases.some(c=>c.id!==value.id && c.caseNumber.trim().toLowerCase()===value.caseNumber.trim().toLowerCase())) throw new Error('案例编号已存在，请使用不同编号'); const i=d.cases.findIndex(c=>c.id===value.id); i<0 ? d.cases.push(updated(value)) : d.cases.splice(i,1,updated(value)); }); setForm(null); goto(`after-sales/${value.id}`); };
  const saveLog = async (value: Followup) => { if(form?.kind!=='log') return; const context=form; await commit(d=> { const records = context.entity==='customer' ? d.customers : context.entity==='project' ? d.projects : d.cases; const target=records.find(r=>r.id===context.id); if(!target) throw new Error('记录已删除，请刷新'); const oldLatest=latestDate(target.logs); const fallback='lastFollowup' in target && target.lastFollowup!==oldLatest ? target.lastFollowup : ''; const i=target.logs.findIndex(l=>l.id===value.id); i<0 ? target.logs.push(value) : target.logs.splice(i,1,value); target.updatedAt=new Date().toISOString(); if('lastFollowup' in target) target.lastFollowup=latestDate(target.logs,fallback); }); setForm(null); };
  const deleteLog = (entity:'customer'|'project'|'case', id:string, log:Followup) => ask({ title:'删除沟通记录',description:`确认永久删除 ${dateText(log.date)} 的这条沟通记录？`,danger:true,action:()=>commit(d=> { const records=entity==='customer'?d.customers:entity==='project'?d.projects:d.cases; const target=records.find(r=>r.id===id); if(!target) throw new Error('记录已删除，请刷新'); const oldLatest=latestDate(target.logs); const fallback='lastFollowup' in target && target.lastFollowup!==oldLatest ? target.lastFollowup : ''; target.logs=target.logs.filter(l=>l.id!==log.id); target.updatedAt=new Date().toISOString(); if('lastFollowup' in target) target.lastFollowup=latestDate(target.logs,fallback); },'沟通记录已删除') });
  const archiveRecord = (entity:'customer'|'project'|'case', record:Customer|Project|AfterSalesCase) => runSafely(()=>commit(d=> { const records=entity==='customer'?d.customers:entity==='project'?d.projects:d.cases; const target=records.find(r=>r.id===record.id); if(target) { target.archived=!target.archived; target.updatedAt=new Date().toISOString(); if('background' in target) target.status=target.archived?'已归档':'暂停跟进'; } }, record.archived?'记录已恢复':'记录已归档，可从「包含归档」中查看'));
  const deleteRecord = (entity:'customer'|'project'|'case', record:Customer|Project|AfterSalesCase) => { if(!data) return; const children=entity==='customer'?`${data.projects.filter(p=>p.customerId===record.id).length} 个项目及 ${data.cases.filter(c=>c.customerId===record.id).length} 个售后案例也将删除。`:entity==='project'?'关联售后案例会保留，并解除项目关联。':''; ask({title:'确认永久删除',description:`将删除「${'name' in record?record.name:record.caseNumber}」及其记录。${children}此操作不可撤销。`,danger:true, action:async()=> { await commit(d=> { if(entity==='customer') { d.customers=d.customers.filter(c=>c.id!==record.id); d.relationships=d.relationships.filter(r=>r.fromCustomerId!==record.id&&r.toCustomerId!==record.id); d.projects=d.projects.filter(p=>p.customerId!==record.id); d.cases=d.cases.filter(c=>c.customerId!==record.id); } else if(entity==='project') { d.projects=d.projects.filter(p=>p.id!==record.id); d.cases=d.cases.map(c=>c.projectId===record.id?updated({...c,projectId:''}):c); } else d.cases=d.cases.filter(c=>c.id!==record.id); },'记录已删除'); goto(entity==='customer'?'customers':entity==='project'?'projects':'after-sales'); } }); };
  const page = path[0] || 'dashboard';
  const selectedCustomer = data?.customers.find(c=>c.id===path[1]);
  const selectedProject = data?.projects.find(p=>p.id===path[1]);
  const selectedCase = data?.cases.find(c=>c.id===path[1]);
  const isDetail = Boolean(path[1]);
  const title = page==='dashboard'?'工作总览':page==='customers'?(isDetail?selectedCustomer?.name??'客户详情':'客户管理'):page==='projects'?(isDetail?selectedProject?.name??'项目详情':'销售项目'):page==='after-sales'?(isDetail?selectedCase?.caseNumber??'售后详情':'售后管理'):page==='topology'?'公司关系拓扑':'数据与备份';
  const descriptions: Record<string,string> = {dashboard:'客户、商机与服务进展，一处掌握。',topology:'用公司节点与关系连线，梳理代理、客户和供应网络。',customers:'每一位客户，一份完整的合作记录。',projects:'独立跟踪每个商机，灵活推进每一个阶段。','after-sales':'独立记录技术支持、返修与客户服务。',settings:'账号协作、报表导出与备份恢复。'};
  if(!data) return <div className="loading-screen"><div className="brand-mark">S</div><h1>SalesMap CRM</h1>{loadError?<><p className="error-message">{loadError}</p><Button variant="primary" onClick={()=>void boot()}>重新加载</Button>{getStorageInfo().mode==='cloud'&&<><Button onClick={()=>{const personal=getStorageInfo().workspaces.find(w=>w.role==='owner');if(personal){switchWorkspace(personal.id);void boot();}}}>返回个人工作空间</Button><a className="btn btn-secondary" href="/signin-with-chatgpt?return_to=%2F" target="_top">重新登录</a></>}</>:<p>正在读取工作空间…</p>}</div>;
  const activeCustomers=data.customers.filter(c=>!c.archived);
  const activeProjects=data.projects.filter(p=>!p.archived && activeCustomers.some(c=>c.id===p.customerId));
  const openProjects=activeProjects.filter(p=>p.status==='进行中');
  const activeCases=data.cases.filter(c=>!c.archived && activeCustomers.some(cu=>cu.id===c.customerId));
  const pendingCases=activeCases.filter(c=>c.status!=='已结案');
  const dueProjects=openProjects.filter(p=>isDue(p.nextFollowup));
  const staleProjects=openProjects.filter(p=>(daysSince(p.lastFollowup)??0)>30);
  const weeklyProjects=openProjects.filter(p=>withinWeek(p.nextFollowup));
  const unknownProjects=openProjects.filter(p=>!p.lastFollowup);
  const sortedProjects=[...activeProjects].sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
  const navItems: {id:string;label:string;english:string;icon:LucideIcon;count?:number}[]=[{id:'dashboard',label:'工作总览',english:'Overview',icon:LayoutDashboard},{id:'customers',label:'客户管理',english:'Customers',icon:Building2,count:activeCustomers.length},{id:'projects',label:'销售项目',english:'Projects',icon:BriefcaseBusiness,count:activeProjects.length},{id:'after-sales',label:'售后管理',english:'After-sales',icon:Wrench,count:pendingCases.length},{id:'topology',label:'关系拓扑',english:'Topology',icon:GitBranch}];
  const countries=[...new Set(data.customers.map(c=>c.country).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'zh-CN'));
  const customerRows=data.customers.filter(c=>(showArchived || !c.archived)&&c.name.toLowerCase().includes(query.trim().toLowerCase())&&(!country||c.country===country)&&(!kind||c.type===kind)&&(!status||c.status===status)).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='country'?a.country.localeCompare(b.country,'zh-CN'):sort==='followup'?(a.nextFollowup||'9999').localeCompare(b.nextFollowup||'9999'):b.updatedAt.localeCompare(a.updatedAt));
  const projectRows=data.projects.filter(p=>(showArchived||(!p.archived&&activeCustomers.some(c=>c.id===p.customerId)))&&`${p.name} ${customerName(data.customers,p.customerId)} ${p.product}`.toLowerCase().includes(query.trim().toLowerCase())&&(!country||p.country===country)&&(!status||p.status===status)&&(!followupFilter || (followupFilter==='due'?p.status==='进行中'&&isDue(p.nextFollowup):followupFilter==='stale'?p.status==='进行中'&&(daysSince(p.lastFollowup)??0)>30:followupFilter==='week'?p.status==='进行中'&&withinWeek(p.nextFollowup):p.status==='进行中'&&!p.lastFollowup))).sort((a,b)=>sort==='name'?a.name.localeCompare(b.name):sort==='followup'?(a.nextFollowup||'9999').localeCompare(b.nextFollowup||'9999'):b.updatedAt.localeCompare(a.updatedAt));
  const caseRows=data.cases.filter(c=>(showArchived||(!c.archived&&activeCustomers.some(cu=>cu.id===c.customerId)))&&`${c.caseNumber} ${customerName(data.customers,c.customerId)} ${c.product} ${c.serialNumbers.join(' ')}`.toLowerCase().includes(query.trim().toLowerCase())&&(!status||c.status===status)).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt));
  const openFilteredProjects = (filter: string) => { goto('projects'); window.setTimeout(()=>setFollowupFilter(filter),20); };
  function ArchiveControl() { return <label className="check-inline"><input type="checkbox" checked={showArchived} onChange={e=>setShowArchived(e.target.checked)} />包含归档</label>; }
  function CustomerTable({rows,compact=false}:{rows:Customer[];compact?:boolean}) { return rows.length?<div className="table-wrap"><table><thead><tr><th>客户名称</th><th>国家 / 类型</th><th>关系状态</th><th>产品兴趣</th><th>销售项目</th><th>下次跟进</th>{!compact&&<th className="actions-head">操作</th>}</tr></thead><tbody>{rows.map(c=><tr key={c.id}><td><a className="record-link" href={`#/customers/${c.id}`}><span className="customer-avatar">{c.name.slice(0,2).toUpperCase()}</span><span><strong>{c.name}</strong><small>{c.contacts[0]?.name||'联系人待补充'}</small></span></a></td><td><div>{flags[c.country]} {c.country||'待补充'}</div><small>{c.type}</small></td><td><Badge tone={tone(c.status)}>{c.archived?'已归档':c.status}</Badge></td><td><div className="tag-list">{c.interests.length?c.interests.slice(0,2).map(i=><span className="product-tag" key={i}>{i}</span>):<small>待补充</small>}{c.interests.length>2&&<small>+{c.interests.length-2}</small>}</div></td><td><span className="number-pill">{data!.projects.filter(p=>p.customerId===c.id&&!p.archived).length}</span></td><td><span className={isDue(c.nextFollowup)?'date-due':''}>{dateText(c.nextFollowup)}</span></td>{!compact&&<td><div className="row-actions"><button className="icon-btn" title={`编辑 ${c.name}`} aria-label={`编辑 ${c.name}`} onClick={()=>setForm({kind:'customer',initial:c})}><Pencil size={15}/></button><button className="icon-btn" title={c.archived?'恢复客户':'归档客户'} aria-label={`${c.archived?'恢复':'归档'} ${c.name}`} onClick={()=>archiveRecord('customer',c)}>{c.archived?<RotateCcw size={15}/>:<Archive size={15}/>}</button><button className="icon-btn delete" aria-label={`删除 ${c.name}`} title="删除客户" onClick={()=>deleteRecord('customer',c)}><Trash2 size={15}/></button></div></td>}</tr>)}</tbody></table></div>:<Empty title="没有匹配的客户" description="调整筛选条件，或新增客户开始记录。"/>; }
  function ProjectTable({rows,hideCustomer=false}:{rows:Project[];hideCustomer?:boolean}) { return rows.length?<div className="table-wrap"><table><thead><tr><th>项目名称 / 产品</th>{!hideCustomer&&<th>关联客户</th>}<th>当前阶段</th><th>金额 / 性质</th><th>状态</th><th>下次跟进</th><th>操作</th></tr></thead><tbody>{rows.map(p=><tr key={p.id}><td><a className="table-title" href={`#/projects/${p.id}`}>{p.name}</a><small>{p.product||'型号待补充'}{p.quantity!==null?` · ${p.quantity.toLocaleString()} 台`:''}</small>{p.archived&&<Badge>已归档</Badge>}</td>{!hideCustomer&&<td><a href={`#/customers/${p.customerId}`} className="subtle-link">{customerName(data!.customers,p.customerId)}</a><small>{p.country||'国家待补充'}</small></td>}<td><span className="stage-dot"/>{stageName(p)}</td><td><span className="money">{amountText(p)}</span><small>{p.amountKind}</small></td><td><Badge tone={tone(p.status)}>{p.status}</Badge></td><td><span className={isDue(p.nextFollowup)&&p.status==='进行中'?'date-due':''}>{dateText(p.nextFollowup)}</span></td><td><div className="row-actions"><button className="icon-btn" aria-label={`编辑 ${p.name}`} onClick={()=>setForm({kind:'project',initial:p})}><Pencil size={15}/></button><button className="icon-btn" aria-label={`${p.archived?'恢复':'归档'} ${p.name}`} onClick={()=>archiveRecord('project',p)}>{p.archived?<RotateCcw size={15}/>:<Archive size={15}/>}</button><button className="icon-btn delete" aria-label={`删除 ${p.name}`} onClick={()=>deleteRecord('project',p)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>:<Empty title="暂无销售项目" description="新增独立项目，分别跟踪阶段、报价与沟通。"/>; }
  function CaseTable({rows}:{rows:AfterSalesCase[]}) { return rows.length?<div className="table-wrap"><table><thead><tr><th>案例编号 / 产品</th><th>关联客户</th><th>当前阶段</th><th>优先级</th><th>状态</th><th>报修日期</th><th>操作</th></tr></thead><tbody>{rows.map(c=><tr key={c.id}><td><a className="table-title" href={`#/after-sales/${c.id}`}>{c.caseNumber}</a><small>{c.product||'型号待补充'}</small>{c.archived&&<Badge>已归档</Badge>}</td><td><a className="subtle-link" href={`#/customers/${c.customerId}`}>{customerName(data!.customers,c.customerId)}</a></td><td>{stageName(c)}</td><td><Badge tone={tone(c.priority)}>{c.priority}</Badge></td><td><Badge tone={tone(c.status)}>{c.status}</Badge></td><td>{dateText(c.reportedDate)}</td><td><div className="row-actions"><button className="icon-btn" aria-label={`编辑 ${c.caseNumber}`} onClick={()=>setForm({kind:'case',initial:c})}><Pencil size={15}/></button><button className="icon-btn" aria-label={`${c.archived?'恢复':'归档'} ${c.caseNumber}`} onClick={()=>archiveRecord('case',c)}>{c.archived?<RotateCcw size={15}/>:<Archive size={15}/>}</button><button className="icon-btn delete" aria-label={`删除 ${c.caseNumber}`} onClick={()=>deleteRecord('case',c)}><Trash2 size={15}/></button></div></td></tr>)}</tbody></table></div>:<Empty title="暂无售后案例" description="可独立创建技术支持或 RMA 案例，也可关联销售项目。"/>; }
  const recordActions=(entity:'customer'|'project'|'case',record:Customer|Project|AfterSalesCase)=> <div className="record-actions"><Button onClick={()=>entity==='customer'?setForm({kind:'customer',initial:record as Customer}):entity==='project'?setForm({kind:'project',initial:record as Project}):setForm({kind:'case',initial:record as AfterSalesCase})}><Pencil size={15}/>编辑信息</Button><Button onClick={()=>archiveRecord(entity,record)}>{record.archived?<RotateCcw size={15}/>:<Archive size={15}/>} {record.archived?'恢复记录':'归档'}</Button><Button variant="ghost" className="text-danger" onClick={()=>deleteRecord(entity,record)}><Trash2 size={15}/>删除</Button></div>;
  const renderLogs=(entity:'customer'|'project'|'case',id:string,logs:Followup[])=> <FollowupTimeline readOnly={storage?.role==='viewer'} logs={logs} title={entity==='customer'?'客户沟通记录':'跟进日志'} onAdd={()=>setForm({kind:'log',entity,id})} onEdit={initial=>setForm({kind:'log',entity,id,initial})} onDelete={log=>deleteLog(entity,id,log)}/>;
  return <div className={`app-shell ${storage?.role==='viewer'?'read-only':''}`}>
    <aside className="sidebar"><a className="brand" href="#/dashboard"><div className="brand-mark"><svg width="27" height="27" viewBox="0 0 28 28" fill="none"><path d="M22 6H12a5 5 0 0 0 0 10h4a3 3 0 0 1 0 6H6M6 22h10a5 5 0 0 0 0-10h-4a3 3 0 0 1 0-6h10" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round"/></svg></div><span>SALESMAP<small>客户与项目管理</small></span></a><div className="workspace-label"><Globe2 size={14}/> SALES WORKSPACE</div><nav aria-label="主导航">{navItems.map(n=><a href={`#/${n.id}`} key={n.id} className={`nav-item ${page===n.id?'active':''}`}><n.icon size={19}/><span>{n.label}</span>{n.count!==undefined&&<span className="nav-count">{n.count}</span>}</a>)}</nav><div className="sidebar-bottom"><a href="#/settings" className={`nav-item ${page==='settings'?'active':''}`}><Settings2 size={19}/><span>数据与备份</span></a><div className="local-label"><span className="status-light"/><span>{storage?.mode==='cloud'?'云端工作空间':'本地工作空间'}<small>{storage?.mode==='cloud'?'账号隔离 · 自动同步':'单用户 · IndexedDB 存储'}</small></span><ShieldCheck size={17}/></div><div className="profile"><div className="profile-avatar">{storage?.user?.name?.slice(0,2).toUpperCase()||'SM'}</div><span>{storage?.user?.name||'个人工作空间'}<small>{storage?.user?.email||'SalesMap CRM'}</small></span></div></div></aside>
    <div className="main-shell"><header className="topbar"><div className="breadcrumb">{storage?.workspaces.find(w=>w.id===storage.currentWorkspaceId)?.name||'个人工作空间'} <ChevronRight size={14}/><span>{isDetail?(page==='customers'?'客户管理':page==='projects'?'销售项目':'售后管理'):title}</span>{isDetail&&<><ChevronRight size={14}/><strong>详情</strong></>}</div><div className="topbar-right"><span><CalendarDays size={14}/>{today()}</span><Badge tone={syncError?'amber':'green'}>{syncError?'同步异常':storage?.mode==='cloud'?'云端已同步':'本地已保存'}</Badge></div></header>
      <main>{syncError&&<div className="warning-box"><p>{syncError}</p><Button onClick={()=>{if(pendingWrites.current||document.querySelector('[role="dialog"]')){notify('请先关闭当前编辑，再重新同步',true);return;}void boot();}}>重新同步</Button></div>}{storage?.role==='viewer'&&<div className="info-banner">当前工作空间为只读权限，可查看与导出记录。</div>}{storage?.mode==='cloud'&&storage.requiresImport&&<div className="info-banner"><span>这是空工作空间。可新增客户，或在数据与备份中导入已有 JSON 备份。</span><a href="#/settings">导入备份</a></div>}<div className="page-heading"><div>{isDetail&&<button className="back-link" onClick={()=>goto(page)}><ArrowLeft size={14}/>返回{page==='customers'?'客户列表':page==='projects'?'项目列表':'售后列表'}</button>}<h1>{title}</h1><p>{isDetail?'查看、编辑并持续跟进这条业务记录。':descriptions[page]??descriptions.settings}</p></div><div className="heading-actions"><Button disabled={exportBusy} onClick={()=>void downloadExcel()}><FileSpreadsheet size={16}/>{exportBusy?'正在导出…':'导出 Excel'}</Button>{(page==='dashboard'||page==='customers')&&<Button variant="primary" onClick={()=>setForm({kind:'customer'})}><Plus size={17}/>新增客户</Button>}{page==='projects'&&!isDetail&&<Button variant="primary" onClick={()=>setForm({kind:'project'})}><Plus size={17}/>新增项目</Button>}{page==='after-sales'&&!isDetail&&<Button variant="primary" onClick={()=>setForm({kind:'case'})}><Plus size={17}/>新增案例</Button>}</div></div>
      {page==='topology'&&<CustomerTopology readOnly={storage?.role==='viewer'} customers={activeCustomers} relationships={data.relationships} onAddRelationship={()=>setForm({kind:'relationship'})} onEditRelationship={initial=>setForm({kind:'relationship',initial})}/>}
      {page==='dashboard'&&<>
        <div className="stats-grid">{[{label:'客户总数',english:'Customers',value:activeCustomers.length,icon:Building2,hint:`${countries.length} 个国家 / 地区`,action:()=>goto('customers'),color:'blue'},{label:'进行中项目',english:'Active projects',value:openProjects.length,icon:BriefcaseBusiness,hint:`共 ${activeProjects.length} 个销售项目`,action:()=>{goto('projects');setTimeout(()=>setStatus('进行中'),20);},color:'indigo'},{label:'待跟进项目',english:'Follow-up due',value:dueProjects.length,icon:Clock3,hint:'今天及已逾期 · 进行中',action:()=>openFilteredProjects('due'),color:'amber'},{label:'待处理售后',english:'Open service cases',value:pendingCases.length,icon:Wrench,hint:'待处理 / 处理中 / 等待客户',action:()=>goto('after-sales'),color:'teal'}].map(k=><button className="stat-card" key={k.label} onClick={k.action}><div className="stat-top"><span>{k.label}</span><span className={`stat-icon ${k.color}`}><k.icon size={20}/></span></div><strong className="stat-number">{k.value}<span>{k.english}</span></strong><small>{k.hint}<ArrowRight size={13}/></small></button>)}</div>
        <div className="dashboard-grid"><section className="panel"><div className="panel-heading"><div><h2>最近更新项目</h2><p>保持商机进展与客户沟通同步</p></div><a className="text-link" href="#/projects">全部项目<ArrowRight size={14}/></a></div><div className="recent-list">{sortedProjects.slice(0,5).map(p=><a className="recent-row" href={`#/projects/${p.id}`} key={p.id}><span className="project-icon"><BriefcaseBusiness size={17}/></span><span className="recent-title"><strong>{p.name}</strong><small>{customerName(data.customers,p.customerId)} · {p.product||'产品待补充'}</small></span><span className="recent-stage">{stageName(p)}<small>{dateText(p.updatedAt)} 更新</small></span><Badge tone={tone(p.status)}>{p.status}</Badge><ChevronRight size={16}/></a>)}{!sortedProjects.length&&<Empty title="暂无项目"/>}</div></section><section className="panel attention-panel"><div className="panel-heading"><div><h2>跟进提醒</h2><p>按日期安排下一步工作</p></div><Clock3 size={19}/></div><button className="attention-item" onClick={()=>openFilteredProjects('week')}><span className="attention-icon blue"><CalendarDays size={19}/></span><span><strong>未来 7 天需要跟进</strong><small>含今天，进行中的项目</small></span><b>{weeklyProjects.length}</b><ChevronRight size={15}/></button><button className="attention-item" onClick={()=>openFilteredProjects('stale')}><span className="attention-icon amber"><CircleAlert size={19}/></span><span><strong>超过 30 天未跟进</strong><small>以最近沟通日期为准</small></span><b>{staleProjects.length}</b><ChevronRight size={15}/></button><button className="attention-item" onClick={()=>openFilteredProjects('unknown')}><span className="attention-icon neutral"><CalendarDays size={19}/></span><span><strong>跟进日期待补充</strong><small>历史记录未提供沟通日期</small></span><b>{unknownProjects.length}</b><ChevronRight size={15}/></button><div className="attention-note">补充项目的下一次跟进日期后，提醒会自动显示在这里。</div></section></div>
        <section className="panel"><div className="panel-heading"><div><h2>客户工作台 <span className="section-count">{activeCustomers.length}</span></h2><p>一个客户，多个独立项目与售后案例</p></div><a className="text-link" href="#/customers">查看全部<ArrowRight size={14}/></a></div><CustomerTable rows={activeCustomers.slice(0,8)} compact/></section>
      </>}
      {page==='customers'&&!isDetail&&<section className="panel"><div className="filter-bar"><div className="search-input"><Search size={16}/><input aria-label="搜索客户名称" placeholder="搜索客户名称…" value={query} onChange={e=>setQuery(e.target.value)}/></div><select aria-label="筛选国家" value={country} onChange={e=>setCountry(e.target.value)}><option value="">全部国家</option>{countries.map(c=><option key={c}>{c}</option>)}</select><select aria-label="筛选客户类型" value={kind} onChange={e=>setKind(e.target.value)}><option value="">全部类型</option>{CUSTOMER_TYPES.map(t=><option key={t}>{t}</option>)}</select><select aria-label="筛选客户状态" value={status} onChange={e=>setStatus(e.target.value)}><option value="">全部状态</option>{CUSTOMER_STATUSES.map(s=><option key={s}>{s}</option>)}</select><select aria-label="客户排序" value={sort} onChange={e=>setSort(e.target.value)}><option value="updated">最近更新</option><option value="name">名称 A → Z</option><option value="country">按国家</option><option value="followup">下次跟进最早</option></select><ArchiveControl/></div><div className="table-caption"><span>共 <strong>{customerRows.length}</strong> 位客户</span><span><SlidersHorizontal size={13}/> 点击客户名称查看详情</span></div><CustomerTable rows={customerRows}/></section>}
      {page==='projects'&&!isDetail&&<section className="panel"><div className="filter-bar"><div className="search-input"><Search size={16}/><input aria-label="搜索项目" placeholder="搜索项目、客户或型号…" value={query} onChange={e=>setQuery(e.target.value)}/></div><select aria-label="项目国家" value={country} onChange={e=>setCountry(e.target.value)}><option value="">全部国家</option>{countries.map(c=><option key={c}>{c}</option>)}</select><select aria-label="项目状态筛选" value={status} onChange={e=>setStatus(e.target.value)}><option value="">全部状态</option>{PROJECT_STATUSES.map(s=><option key={s}>{s}</option>)}</select><select aria-label="跟进筛选" value={followupFilter} onChange={e=>setFollowupFilter(e.target.value)}><option value="">全部跟进</option><option value="due">今天及逾期</option><option value="week">未来 7 天</option><option value="stale">超过 30 天未跟进</option><option value="unknown">跟进日期待补充</option></select><select aria-label="项目排序" value={sort} onChange={e=>setSort(e.target.value)}><option value="updated">最近更新</option><option value="name">按名称</option><option value="followup">下次跟进最早</option></select><ArchiveControl/></div><div className="table-caption"><span>共 <strong>{projectRows.length}</strong> 个项目</span><span>框架与潜在需求按金额性质分别记录</span></div><ProjectTable rows={projectRows}/></section>}
      {page==='after-sales'&&!isDetail&&<section className="panel"><div className="filter-bar"><div className="search-input"><Search size={16}/><input aria-label="搜索售后" placeholder="搜索案例、客户、型号或 SN…" value={query} onChange={e=>setQuery(e.target.value)}/></div><select aria-label="售后状态筛选" value={status} onChange={e=>setStatus(e.target.value)}><option value="">全部状态</option>{CASE_STATUSES.map(s=><option key={s}>{s}</option>)}</select><ArchiveControl/></div><div className="table-caption"><span>共 <strong>{caseRows.length}</strong> 个案例</span><span>技术支持与销售流程独立推进</span></div><CaseTable rows={caseRows}/></section>}
      {page==='customers'&&isDetail&&(selectedCustomer?<>
        <section className="panel customer-journey-panel">
          <div className="tabs-row">
            <div className="tabs" role="tablist">{[{id:'projects',name:'销售项目',count:data.projects.filter(p=>p.customerId===selectedCustomer.id&&!p.archived).length},{id:'cases',name:'售后案例',count:data.cases.filter(c=>c.customerId===selectedCustomer.id&&!c.archived).length},{id:'logs',name:'客户沟通记录',count:selectedCustomer.logs.length}].map(t=><button role="tab" aria-selected={tab===t.id} className={tab===t.id?'selected':''} key={t.id} onClick={()=>setTab(t.id as typeof tab)}>{t.name}<span>{t.count}</span></button>)}</div>
            <div className="tab-actions">
              {tab!=='logs'&&<><div className="journey-view-switch" role="group" aria-label="项目显示方式"><button aria-pressed={customerView==='map'} className={customerView==='map'?'selected':''} onClick={()=>setCustomerView('map')}><GitBranch size={13}/>节点线图</button><button aria-pressed={customerView==='table'} className={customerView==='table'?'selected':''} onClick={()=>setCustomerView('table')}><List size={13}/>表格列表</button></div><ArchiveControl/></>}
              {tab==='projects'&&<Button variant="primary" onClick={()=>setForm({kind:'project',customerId:selectedCustomer.id})}><Plus size={16}/>新增项目</Button>}
              {tab==='cases'&&<Button variant="primary" onClick={()=>setForm({kind:'case',customerId:selectedCustomer.id})}><Plus size={16}/>新增案例</Button>}
            </div>
          </div>
          {tab!=='logs'&&customerView==='map'&&<CustomerJourneyMap readOnly={storage?.role==='viewer'} customer={selectedCustomer} projects={data.projects.filter(p=>p.customerId===selectedCustomer.id&&(showArchived||!p.archived))} cases={data.cases.filter(c=>c.customerId===selectedCustomer.id&&(showArchived||!c.archived))} service={tab==='cases'} onEdit={record=>'caseNumber' in record?setForm({kind:'case',initial:record}):setForm({kind:'project',initial:record})} onStageChange={(entity,id,stages,currentStageId)=>commit(d=>{const record=entity==='project'?d.projects.find(p=>p.id===id):d.cases.find(c=>c.id===id);if(!record)throw new Error('记录已删除，请刷新页面');record.stages=stages;record.currentStageId=currentStageId;record.updatedAt=new Date().toISOString();})}/>} 
          {tab==='projects'&&customerView==='table'&&<ProjectTable hideCustomer rows={data.projects.filter(p=>p.customerId===selectedCustomer.id&&(showArchived||!p.archived))}/>}
          {tab==='cases'&&customerView==='table'&&<CaseTable rows={data.cases.filter(c=>c.customerId===selectedCustomer.id&&(showArchived||!c.archived))}/>}
          {tab==='logs'&&<div className="inner-panel">{renderLogs('customer',selectedCustomer.id,selectedCustomer.logs)}</div>}
        </section>
        <section className="panel customer-context">
          <div className="customer-context-bar"><div className="customer-context-identity"><Building2 size={17}/><strong>{selectedCustomer.name}</strong><span>{selectedCustomer.country||'国家待补充'} · {selectedCustomer.type}</span><Badge tone={tone(selectedCustomer.status)}>{selectedCustomer.archived?'已归档':selectedCustomer.status}</Badge></div>{recordActions('customer',selectedCustomer)}</div>
          <details><summary>客户背景与联系人 · {selectedCustomer.contacts.length} 位联系人 · 下次跟进 {dateText(selectedCustomer.nextFollowup)}</summary>
            <div className="customer-info-grid"><div><h3>客户背景</h3><p className="pre-wrap">{selectedCustomer.background||'待补充'}</p><div className="tag-list">{selectedCustomer.interests.map(i=><span className="product-tag" key={i}>{i}</span>)}</div>{selectedCustomer.notes&&<p className="pre-wrap note-text">备注：{selectedCustomer.notes}</p>}</div><div><h3>联系人 <span className="section-count">{selectedCustomer.contacts.length}</span></h3>{selectedCustomer.contacts.length?selectedCustomer.contacts.map(c=><div className="contact-card" key={c.id}><strong>{c.name||'姓名待补充'}<small>{c.title}</small></strong>{c.email&&<a href={`mailto:${c.email}`}><Mail size={13}/>{c.email}</a>}{c.phone&&<span><Phone size={13}/>{c.phone}</span>}</div>):<p className="muted">联系人信息待补充，可通过「编辑信息」添加。</p>}<div className="followup-dates"><span>最近跟进 <strong>{dateText(selectedCustomer.lastFollowup)}</strong></span><span>下次跟进 <strong className={isDue(selectedCustomer.nextFollowup)?'date-due':''}>{dateText(selectedCustomer.nextFollowup)}</strong></span></div></div></div>
          </details>
        </section>
      </>:<Empty title="客户不存在" description="记录可能已被删除，请返回客户列表。"/>)}
      {page==='projects'&&isDetail&&(selectedProject?<>
        <section className="panel detail-summary"><div className="summary-top"><div><a className="text-link" href={`#/customers/${selectedProject.customerId}`}><Building2 size={15}/>{customerName(data.customers,selectedProject.customerId)}</a><div className="summary-status"><Badge tone={tone(selectedProject.status)}>{selectedProject.status}</Badge>{selectedProject.archived&&<Badge>已归档</Badge>}<span>{selectedProject.country||'国家待补充'}</span></div></div>{recordActions('project',selectedProject)}</div><div className="detail-fields">{[['产品型号',selectedProject.product||'待补充'],['预计数量',selectedProject.quantity===null?'待补充':`${selectedProject.quantity.toLocaleString()} 台`],['项目金额',amountText(selectedProject)],['金额性质',selectedProject.amountKind],['已回款',selectedProject.receivedAmount===null?'待补充':`${selectedProject.currency} ${selectedProject.receivedAmount.toLocaleString()}`],['关联终端 / 代理商',selectedProject.relatedParty||'未设置'],['订单号 / PO',selectedProject.po||'待补充'],['PI 编号',selectedProject.pi||'待补充'],['负责人',selectedProject.owner||'待补充'],['最近跟进',dateText(selectedProject.lastFollowup)],['下次跟进',dateText(selectedProject.nextFollowup)]].map(([k,v])=><div key={k}><small>{k}</small><strong>{v}</strong></div>)}</div>{selectedProject.notes&&<div className="record-note"><strong>商务进展与备注</strong><p className="pre-wrap">{selectedProject.notes}</p></div>}</section>
        <section className="panel workflow-panel"><StageBoard readOnly={storage?.role==='viewer'} stages={selectedProject.stages} currentStageId={selectedProject.currentStageId} onChange={(stages,currentStageId)=>commit(d=>{const p=d.projects.find(p=>p.id===selectedProject.id);if(p){p.stages=stages;p.currentStageId=currentStageId;p.updatedAt=new Date().toISOString();}})}/></section><section className="panel inner-panel">{renderLogs('project',selectedProject.id,selectedProject.logs)}</section>
      </>:<Empty title="项目不存在" description="记录可能已被删除，请返回项目列表。"/>)}
      {page==='after-sales'&&isDetail&&(selectedCase?<>
        <section className="panel detail-summary"><div className="summary-top"><div><a className="text-link" href={`#/customers/${selectedCase.customerId}`}><Building2 size={15}/>{customerName(data.customers,selectedCase.customerId)}</a><div className="summary-status"><Badge tone={tone(selectedCase.status)}>{selectedCase.status}</Badge><Badge tone={tone(selectedCase.priority)}>{selectedCase.priority}优先级</Badge>{selectedCase.archived&&<Badge>已归档</Badge>}</div></div>{recordActions('case',selectedCase)}</div><div className="detail-fields"><div><small>产品型号</small><strong>{selectedCase.product||'待补充'}</strong></div><div><small>设备 SN</small><strong className="pre-wrap">{selectedCase.serialNumbers.join('\n')||'待补充'}</strong></div><div><small>关联销售项目</small>{selectedCase.projectId?<a href={`#/projects/${selectedCase.projectId}`}>{data.projects.find(p=>p.id===selectedCase.projectId)?.name}</a>:<strong>独立售后案例</strong>}</div><div><small>报修日期</small><strong>{dateText(selectedCase.reportedDate)}</strong></div><div><small>下次跟进</small><strong>{dateText(selectedCase.nextFollowup)}</strong></div></div><div className="record-note"><strong>故障描述</strong><p className="pre-wrap">{selectedCase.issue||'待补充'}</p><strong>下一步计划</strong><p className="pre-wrap">{selectedCase.nextStep||'待补充'}</p></div></section>
        <section className="panel workflow-panel"><StageBoard readOnly={storage?.role==='viewer'} service stages={selectedCase.stages} currentStageId={selectedCase.currentStageId} onChange={(stages,currentStageId)=>commit(d=>{const c=d.cases.find(c=>c.id===selectedCase.id);if(c){c.stages=stages;c.currentStageId=currentStageId;c.updatedAt=new Date().toISOString();}})}/></section><section className="panel inner-panel">{renderLogs('case',selectedCase.id,selectedCase.logs)}</section>
      </>:<Empty title="售后案例不存在" description="记录可能已被删除，请返回售后列表。"/>)}
      {page==='settings'&&<><WorkspacePanel info={storage} onChange={changeWorkspace} onRefresh={boot}/><div className="settings-grid"><section className="panel settings-card"><span className="settings-icon"><FileSpreadsheet size={25}/></span><h2>工作报表</h2><p>导出全部客户、销售项目与售后案例，包含阶段备注与沟通历史。金额保留原币种，已回款与框架金额分别标注。</p><Button variant="primary" disabled={exportBusy} onClick={()=>void downloadExcel()}><FileSpreadsheet size={16}/>{exportBusy?'正在生成…':'导出 Excel 报表'}</Button></section><section className="panel settings-card"><span className="settings-icon"><Database size={25}/></span><h2>备份全部数据</h2><p>将完整工作空间下载为 JSON 文件，包含归档记录、联系人、项目阶段与日志。建议每周及重要修改后备份。</p><Button onClick={downloadBackup}><ArrowDownToLine size={16}/>下载 JSON 备份</Button><Button variant="ghost" onClick={()=>setViewBackup(true)}>查看 / 复制 JSON</Button></section><section className="panel settings-card"><span className="settings-icon"><Upload size={25}/></span><h2>恢复备份</h2><p>选择本系统生成的 JSON 备份，先检查记录数量，再确认替换。恢复前会自动下载当前数据的一份备份。</p><Button disabled={storage?.role==='viewer'} onClick={()=>importRef.current?.click()}><Upload size={16}/>选择 JSON 备份</Button><Button variant="ghost" disabled={storage?.role==='viewer'} onClick={()=>{setBackupText('' );setBackupTextError('');setPasteBackup(true);}}>粘贴备份 JSON</Button></section></div><section className="panel storage-info"><h2><ShieldCheck size={19}/>{storage?.mode==='cloud'?'云端数据说明':'本地数据说明'}</h2><dl><div><dt>存储位置</dt><dd>{storage?.mode==='cloud'?`当前账号工作空间 · ${window.location.origin}`:`当前浏览器 · ${window.location.origin} · IndexedDB`}</dd></div><div><dt>当前记录</dt><dd>{data.customers.length} 位客户 / {data.projects.length} 个项目 / {data.cases.length} 个售后案例（包含归档）</dd></div><div><dt>最近保存</dt><dd>{new Date(data.updatedAt).toLocaleString('zh-CN')} · 版本 {data.revision}</dd></div></dl><p>{storage?.mode==='cloud'?'用同一账号在另一台电脑登录，即可读取云端数据。页面每 15 秒检查更新；编辑时暂停刷新。多人同时保存出现冲突时，请保留草稿后重新加载最新数据。定期下载 JSON 备份。':'固定使用同一个浏览器及本地地址。可通过 JSON 备份迁移；清除网站数据会影响本地记录。'}</p>{storage?.mode==='local'&&<Button onClick={()=>runSafely(async()=>{if(!navigator.storage?.persist)throw new Error('当前浏览器不支持持久存储申请');const granted=await navigator.storage.persist();notify(granted?'浏览器已允许持久存储':'浏览器暂未允许持久存储，请继续定期备份');})}><ShieldCheck size={15}/>申请浏览器持久存储</Button>}</section></>}
      </main><footer>SALESMAP · 客户与项目管理<span>{storage?.mode==='cloud'?'独立账户 · 协作工作空间':'本地优先 · 数据由你掌握'}</span></footer>
    </div>
    <input ref={importRef} type="file" accept=".json,application/json" aria-label="选择备份文件" hidden onChange={e=>void selectBackup(e.target.files?.[0])}/>
    {form?.kind==='relationship'&&<RelationshipForm initial={form.initial} customers={data.customers} onSave={saveRelationship} onClose={()=>setForm(null)} onDelete={form.initial?()=>{const id=form.initial!.id;setForm(null);ask({title:'删除公司关系',description:'确认永久删除这条关系连线？公司和项目会保留。',danger:true,action:()=>commit(d=>{d.relationships=d.relationships.filter(r=>r.id!==id);},'关系已删除')});}:undefined}/>}
    {form?.kind==='customer'&&<CustomerForm initial={form.initial} onSave={saveCustomer} onClose={()=>setForm(null)}/>}
    {form?.kind==='project'&&<ProjectForm initial={form.initial} customerId={form.customerId} customers={data.customers} onSave={saveProject} onClose={()=>setForm(null)}/>}
    {form?.kind==='case'&&<CaseForm initial={form.initial} customerId={form.customerId} customers={data.customers} projects={data.projects} onSave={saveCase} onClose={()=>setForm(null)}/>}
    {form?.kind==='log'&&<FollowupForm initial={form.initial} onSave={saveLog} onClose={()=>setForm(null)}/>}
    {viewBackup&&<Modal title="当前完整数据备份" wide onClose={()=>setViewBackup(false)}><p className="muted">此 JSON 包含当前全部客户、项目、售后及记录，可复制到另一台电脑或云端工作空间恢复。</p><label className="field"><span>完整备份 JSON</span><textarea rows={14} readOnly value={JSON.stringify(buildBackup(data),null,2)} spellCheck={false}/></label><div className="form-actions"><Button onClick={()=>{void navigator.clipboard.writeText(JSON.stringify(buildBackup(data),null,2)).then(()=>notify('完整备份已复制')).catch(()=>notify('复制失败，请手动选择文本复制',true));}}>复制完整备份</Button><Button onClick={()=>setViewBackup(false)}>关闭</Button></div></Modal>}
    {pasteBackup&&<Modal title="粘贴 JSON 备份" onClose={()=>setPasteBackup(false)} wide><p className="muted">粘贴本系统生成的完整 JSON 备份内容。下一步会检查数据并显示恢复预览，此处不会直接覆盖记录。</p><label className="field"><span>备份 JSON 内容</span><textarea rows={12} spellCheck={false} value={backupText} onChange={e=>setBackupText(e.target.value)} placeholder="粘贴完整备份 JSON…"/></label>{backupTextError&&<p className="form-error" role="alert">{backupTextError}</p>}<div className="form-actions"><Button onClick={()=>setPasteBackup(false)}>取消</Button><Button variant="primary" disabled={!backupText.trim()} onClick={previewBackupText}>校验并预览</Button></div></Modal>}
    {confirmation&&<Modal title={confirmation.title} onClose={()=>{if(!confirmBusy)setConfirmation(null);}}><p className="confirmation-description">{confirmation.description}</p>{confirmError&&<p role="alert" className="error-message">{confirmError}</p>}<div className="form-actions"><Button disabled={confirmBusy} onClick={()=>setConfirmation(null)}>取消</Button><Button variant={confirmation.danger?'danger':'primary'} disabled={confirmBusy} onClick={()=>{setConfirmBusy(true);void confirmation.action().then(()=>setConfirmation(null)).catch(e=>setConfirmError(errorText(e))).finally(()=>setConfirmBusy(false));}}>{confirmBusy?'正在处理…':'确认删除'}</Button></div></Modal>}
    {restore&&<Modal title="确认恢复备份" onClose={()=>{if(!restoreBusy)setRestore(null);}}><div className="warning-box"><CircleAlert size={20}/><p>恢复会替换当前工作空间中的全部记录，包括归档、备注及日志。恢复前将自动下载当前数据备份。</p></div><div className="restore-counts"><span><strong>{restore.customers.length}</strong>客户</span><span><strong>{restore.projects.length}</strong>销售项目</span><span><strong>{restore.cases.length}</strong>售后案例</span></div><p className="muted">备份最近更新：{new Date(restore.updatedAt).toLocaleString('zh-CN')}</p><label className="field"><span>输入「恢复」以确认替换</span><input value={restoreWord} onChange={e=>setRestoreWord(e.target.value)} placeholder="恢复" disabled={restoreBusy}/></label>{restoreError&&<p role="alert" className="error-message">{restoreError}</p>}<div className="form-actions"><Button disabled={restoreBusy} onClick={()=>setRestore(null)}>取消</Button><Button variant="danger" disabled={restoreWord!=='恢复'||restoreBusy} onClick={()=>void restoreBackup()}>{restoreBusy?'正在恢复…':'确认恢复全部数据'}</Button></div></Modal>}
    {inviteToken&&storage?.mode==='cloud'&&<Modal title="接受工作空间邀请" onClose={()=>setInviteToken('')}><p>当前登录邮箱：{storage.user?.email}。接受后可在数据与备份中切换到同事的工作空间；你的个人数据会保留。</p>{inviteError&&<p className="form-error" role="alert">{inviteError}</p>}<div className="form-actions"><Button disabled={inviteBusy} onClick={()=>setInviteToken('')}>取消</Button><Button variant="primary" disabled={inviteBusy} onClick={()=>{setInviteBusy(true);setInviteError('');void fetch('/api/invites/accept',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify({token:inviteToken})}).then(async response=>{const value=await response.json() as {error?:string;workspaceId:string};if(!response.ok)throw new Error(value.error||'邀请无法接受');await refreshStorageInfo();await switchWorkspace(value.workspaceId);const loaded=await loadData();applyLoaded(loaded);setStorage(getStorageInfo());setInviteToken('');window.history.replaceState(null,'',window.location.pathname+window.location.hash);notify('已加入工作空间');}).catch(e=>setInviteError(errorText(e))).finally(()=>setInviteBusy(false));}}>{inviteBusy?'正在加入…':'接受邀请'}</Button></div></Modal>}
    {notice&&<div role={notice.error?'alert':'status'} className={`toast ${notice.error?'toast-error':''}`}>{notice.error?<CircleAlert size={18}/>:<CheckCircle2 size={18}/>}<span>{notice.message}</span><button aria-label="关闭提示" onClick={()=>setNotice(null)}>×</button></div>}
  </div>;
}





